package com.example.mobile_app.presentation.navigation

import androidx.compose.runtime.Composable
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.remember
import androidx.compose.runtime.getValue
import androidx.compose.runtime.setValue
import androidx.navigation.NavHostController
import androidx.navigation.compose.NavHost
import androidx.navigation.compose.composable
import androidx.navigation.compose.rememberNavController
import androidx.compose.runtime.rememberCoroutineScope
import com.example.mobile_app.presentation.auth.rememberAuthCoordinator
import com.example.mobile_app.presentation.screens.HomeScreen
import com.example.mobile_app.presentation.screens.LoginScreen
import com.example.mobile_app.presentation.screens.RegisterScreen
import com.example.mobile_app.presentation.screens.VerifyEmailScreen
import kotlinx.coroutines.launch

private object Routes {
    const val Login = "login"
    const val Register = "register"
    const val VerifyEmail = "verify_email"
    const val Home = "home"
}

@Composable
fun AppNavigation(navController: NavHostController = rememberNavController()) {
    val authCoordinator = rememberAuthCoordinator()
    val scope = rememberCoroutineScope()
    var verifyNotice by remember { mutableStateOf<String?>(null) }

    NavHost(
        navController = navController,
        startDestination = if (authCoordinator.tokenManager.hasToken()) Routes.Home else Routes.Login,
    ) {
        composable(Routes.Login) {
            LoginScreen(
                authCoordinator = authCoordinator,
                onLoginSuccess = {
                    navController.navigate(Routes.Home) {
                        popUpTo(Routes.Login) { inclusive = true }
                    }
                },
                onRegisterClick = {
                    navController.navigate(Routes.Register)
                },
                onVerifyEmailClick = {
                    navController.navigate(Routes.VerifyEmail)
                },
            )
        }
        composable(Routes.Register) {
            RegisterScreen(
                authCoordinator = authCoordinator,
                onRegisterBack = {
                    navController.popBackStack()
                },
                onRegisterSuccess = { message ->
                    verifyNotice = message
                    navController.navigate(Routes.VerifyEmail) {
                        popUpTo(Routes.Register) { inclusive = true }
                    }
                },
            )
        }
        composable(Routes.VerifyEmail) {
            VerifyEmailScreen(
                authCoordinator = authCoordinator,
                noticeMessage = verifyNotice,
                onBackToLogin = {
                    verifyNotice = null
                    navController.navigate(Routes.Login) {
                        popUpTo(Routes.VerifyEmail) { inclusive = true }
                    }
                },
            )
        }
        composable(Routes.Home) {
            HomeScreen(
                onLogout = {
                    scope.launch {
                        runCatching {
                            authCoordinator.logoutUseCase()
                        }
                        navController.navigate(Routes.Login) {
                            popUpTo(Routes.Home) { inclusive = true }
                        }
                    }
                },
            )
        }
    }
}

