@Composable fun RegistrationSuccessScreen( onBackToLogin: () -> Unit, ) { Column( modifier = Modifier .fillMaxSize() .padding(24.dp), verticalArrangement = Arrangement.Center, horizontalAlignment = Alignment.CenterHorizontally, ) { Text( text = "¡Registro completado!", style = MaterialTheme.typography.headlineMedium, ) Spacer(modifier = Modifier.height(16.dp)) Text( text = "Gracias por darte de alta. Un administrador de tu organización debe verificar tu cuenta.", style = MaterialTheme.typography.bodyLarge, ) Spacer(modifier = Modifier.height(24.dp)) Text( text = "Te notificaremos por email cuando tu cuenta haya sido verificada.", style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurfaceVariant, ) Spacer(modifier = Modifier.height(32.dp)) Button( onClick = onBackToLogin, modifier = Modifier.fillMaxWidth(), ) { Text("Volver al login") } } }
